// Experimental offline adapter. No ROS, GT, prior map or LIO pose input.
#include "experimental_frontend.hpp"
#include "global_relocalization/raw_preprocessing.hpp"
#include <pcl/io/pcd_io.h>
#include <pcl/common/transforms.h>
#include <nlohmann/json.hpp>
#include <fstream>
#include <filesystem>
#include <iostream>
#include <random>
using namespace global_relocalization;using Json=nlohmann::json;namespace fs=std::filesystem;
Eigen::Isometry3d rigid(const Json & a){Eigen::Isometry3d t;for(int r=0;r<4;++r)for(int c=0;c<4;++c)t.matrix()(r,c)=a[r][c].get<double>();return t;}
Json mat(const Eigen::Isometry3d & t){Json j=Json::array();for(int r=0;r<4;++r)j.push_back({t.matrix()(r,0),t.matrix()(r,1),t.matrix()(r,2),t.matrix()(r,3)});return j;}
RawFrontendParams parameters(const Json & j){RawFrontendParams p;
#define READ(x) if(j.contains(#x))p.x=j.at(#x).get<decltype(p.x)>();
READ(range_filter);READ(deterministic);READ(imu_rotation_prior);READ(numerical_recovery);READ(stationary_translation_prior);READ(stationary_translation_sigma_floor);READ(submap_scans);READ(stationary_duration);READ(stationary_min_samples);READ(min_range);READ(max_range);READ(gyro_noise_density);READ(rotation_sigma_floor);READ(leaf_size);READ(max_correspondence);READ(max_iterations);READ(retry_iterations);READ(max_fitness);READ(min_inlier_ratio);READ(max_base_linear_speed);READ(max_base_translation_step);READ(max_imu_gap);READ(max_scan_gap);READ(min_geometry_eigen_ratio);READ(min_information_eigen_ratio);
#undef READ
p.record_iterations=true;return p;}
RawImuSample imu(const Json & row){RawImuSample s;s.stamp=row[0];for(int k=0;k<3;++k){s.angular_velocity[k]=row[1+k];s.linear_acceleration[k]=row[4+k];}return s;}
Eigen::Vector3d omegaAt(const std::vector<RawImuSample> & samples,double stamp){auto it=std::lower_bound(samples.begin(),samples.end(),stamp,[](const auto & s,double t){return s.stamp<t;});if(it==samples.end()||it==samples.begin()&&it->stamp>stamp)throw std::runtime_error("gyro endpoint has no bracket");if(it->stamp==stamp)return it->angular_velocity;const auto & a=*(it-1);return a.angular_velocity+(it->angular_velocity-a.angular_velocity)*((stamp-a.stamp)/(it->stamp-a.stamp));}
Eigen::Matrix3d carriedGauge(const TrustedCalibration & c,const std::vector<RawImuSample> & samples,double end){auto r=c.gravityAlignment();double t=c.stamp();Eigen::Vector3d w=omegaAt(samples,t)-c.bias();auto step=[&](double next,const Eigen::Vector3d & raw){auto nw=raw-c.bias();Eigen::Vector3d angle=.5*(w+nw)*(next-t);if(angle.norm()>1e-12)r=r*Eigen::AngleAxisd(angle.norm(),angle.normalized()).toRotationMatrix();t=next;w=nw;};for(const auto & s:samples)if(s.stamp>c.stamp()&&s.stamp<end)step(s.stamp,s.angular_velocity);step(end,omegaAt(samples,end));return r;}
Json result(const RawFrontendResult & r,double stamp){Json attempts=Json::array();for(const auto & a:r.registration_attempts)attempts.push_back({{"attempt",a.attempt},{"iterations",a.iterations},{"converged",a.converged},{"rejected_gates",a.rejected_gates},{"fitness",a.fitness},{"inlier_ratio",a.inlier_ratio}});Json j={{"stamp",stamp},{"accepted",r.accepted},{"reason",r.reason},{"failure_class",r.failure_class},{"reference_from_sensor",mat(r.reference_from_sensor)},{"reference_from_base",mat(r.reference_from_base)},{"gyro_bias",{r.gyro_bias.x(),r.gyro_bias.y(),r.gyro_bias.z()}},{"fitness",r.fitness},{"inlier_ratio",r.inlier_ratio},{"geometry_eigen_ratio",r.geometry_eigen_ratio},{"information_eigen_ratio",r.information_eigen_ratio},{"translation_step",r.translation_step},{"linear_speed",r.linear_speed},{"rotation_prior_error",r.rotation_prior_error},{"translation_prior_sigma",r.translation_prior_sigma},{"translation_prior_weight",r.translation_prior_weight},{"processing_sec",r.processing_sec},{"rejected_gates",r.rejected_gates},{"registration_attempts",attempts}};if(!r.accepted){j["iteration_trace"]=Json::array();for(const auto & q:r.iteration_trace)j["iteration_trace"].push_back({{"attempt",q.attempt},{"iteration",q.iteration},{"inner",q.inner},{"objective",q.objective},{"candidate_objective",q.candidate_objective},{"accepted",q.accepted},{"increment",std::vector<double>(q.increment.data(),q.increment.data()+6)}});}return j;}
int selfTest(){RawFrontendParams p;p.stationary_duration=2.;p.deterministic=true;p.range_filter=true;p.submap_scans=20;p.max_correspondence=.3;p.max_fitness=.18;p.stationary_translation_prior=true;auto I=Eigen::Isometry3d::Identity();Cloud cloud;std::mt19937 g(17);std::uniform_real_distribution<float>d(-3,3);for(int i=0;i<1000;++i)cloud.emplace_back(d(g),d(g),d(g));ExperimentalCalibratedFrontend f(p,I,I);bool refused=false;try{f.exportCalibration(std::string(64,'a'));}catch(...){refused=true;}if(!refused)return 1;for(int k=0;k<=200;++k){RawImuSample s;s.stamp=k*.01;s.linear_acceleration<<0,0,9.81;if(!f.addImu(s))return 2;}if(!f.processScan(cloud,2.).accepted)return 3;auto c=f.exportCalibration(std::string(64,'a'));
for(int check=0;check<3;++check){auto q=p;auto B=I;double t=12.;if(check==0)q.max_correspondence=.5;if(check==1)B.translation().x()=.01;if(check==2)t=1.;ExperimentalCalibratedFrontend bad(q,I,B);bool fail=false;try{bad.restoreLocalMap(c,Eigen::Matrix3d::Identity(),t);}catch(...){fail=true;}if(!fail)return 4+check;}
ExperimentalCalibratedFrontend ordinary(p,I,I),restored(p,I,I);Eigen::Matrix3d gauge=(Eigen::AngleAxisd(.3,Eigen::Vector3d::UnitX())*Eigen::AngleAxisd(.4,Eigen::Vector3d::UnitZ())).toRotationMatrix();restored.restoreLocalMap(c,gauge,12.);for(int k=0;k<=203;++k){RawImuSample s;s.stamp=9.97+k*.01;s.angular_velocity<<0,0,.3;s.linear_acceleration<<0,0,9.81;ordinary.addImu(s);restored.addImu(s);}if(ordinary.processScan(cloud,12.).accepted)return 7;const auto r=restored.processScan(cloud,12.);if(!r.accepted||!r.reference_from_sensor.rotation().isApprox(gauge,1e-12)||r.gyro_bias.norm()>1e-15)return 8;std::cout<<"trusted calibration contract passed: untrusted refusal, param/extrinsic/time guards, ordinary dynamic initialization refusal, carried calibrated gauge\n";return 0;}
int main(int argc,char ** argv){if(argc==2&&std::string(argv[1])=="--self-test")return selfTest();if(argc!=3){std::cerr<<"usage: offline_station_submaps INPUT.json OUTPUT_DIRECTORY\n";return 2;}try{Json input;std::ifstream(argv[1])>>input;fs::path out(argv[2]);if(fs::exists(out))throw std::runtime_error("output exists");fs::create_directories(out);Json raw;std::ifstream(input.at("imu_samples_json").get<std::string>())>>raw;std::vector<RawImuSample> samples;for(const auto & row:raw)samples.push_back(imu(row));for(size_t k=1;k<samples.size();++k)if(samples[k].stamp<=samples[k-1].stamp||samples[k].stamp-samples[k-1].stamp>.035)throw std::runtime_error("full-source IMU continuity failed");auto p=parameters(input.at("params"));auto si=rigid(input.at("sensor_from_imu")),bs=rigid(input.at("base_from_sensor"));ExperimentalCalibratedFrontend original(p,si,bs);const double calibration_stamp=input.at("calibration_scan").at("stamp");for(const auto & s:samples)if(s.stamp<=calibration_stamp+.01)if(!original.addImu(s))throw std::runtime_error("calibration IMU rejected");Cloud initial;if(pcl::io::loadPCDFile(input.at("calibration_scan").at("path").get<std::string>(),initial)<0)throw std::runtime_error("calibration cloud unavailable");const auto initial_result=original.processScan(initial,calibration_stamp);if(!initial_result.accepted)throw std::runtime_error("real initial calibration scan rejected: "+initial_result.reason);const auto calibration=original.exportCalibration(input.at("calibration_source_sha256"));Json snapshot={{"source_sha256",calibration.sourceSHA256()},{"calibration_stamp",calibration.stamp()},{"gyro_bias",{calibration.bias().x(),calibration.bias().y(),calibration.bias().z()}},{"sample_variance",calibration.sampleVariance()},{"bias_variance",calibration.biasVariance()},{"generated_from_actual_accepted_initial_scan",true},{"parameters_and_extrinsics_checked_on_every_restore",true},{"initial_result",result(initial_result,calibration_stamp)}};std::ofstream(out/"trusted_calibration.json")<<snapshot.dump(2)<<'\n';Json all={{"GT_used_by_estimator",false},{"local_initial_rotation_is_rigid_gauge_only",true},{"global_map_exported",false},{"stations",Json::array()}};
for(const auto & station:input.at("stations")){fs::path directory=out/station.at("id").get<std::string>();fs::create_directories(directory);ExperimentalCalibratedFrontend frontend(p,si,bs);const double first=station.at("scans").at(0).at("stamp");const auto rotation=carriedGauge(calibration,samples,first);frontend.restoreLocalMap(calibration,rotation,first);size_t next=std::lower_bound(samples.begin(),samples.end(),first-.02,[](const auto & s,double t){return s.stamp<t;})-samples.begin();Cloud fused;Json poses=Json::array();size_t accepted=0;bool any_fault=false;for(const auto & scan:station.at("scans")){const double stamp=scan.at("stamp");for(;next<samples.size()&&samples[next].stamp<=stamp+.01;++next)if(!frontend.addImu(samples[next]))throw std::runtime_error("station IMU rejected");Cloud cloud;if(pcl::io::loadPCDFile(scan.at("path").get<std::string>(),cloud)<0)throw std::runtime_error("station raw cloud unavailable");const auto r=frontend.processScan(cloud,stamp,true);poses.push_back(result(r,stamp));if(r.accepted){++accepted;Cloud world;pcl::transformPointCloud(r.filtered_sensor_cloud,world,r.reference_from_sensor.matrix().cast<float>());fused+=world;}else any_fault=true;}std::ofstream(directory/"poses.json")<<poses.dump(2)<<'\n';auto reduced=deterministicVoxel(fused,.05);const std::string file=any_fault?"incomplete_prefix_cloud.pcd":"local_cloud.pcd";if(!reduced->empty())pcl::io::savePCDFileBinary((directory/file).string(),*reduced);Json summary={{"id",station.at("id")},{"source_label",station.at("source_label")},{"input_frames",poses.size()},{"accepted_frames",accepted},{"complete",!any_fault&&accepted==poses.size()},{"fault_explicit",any_fault},{"cloud_points",reduced->size()},{"cloud_file",file},{"calibration_carried",true},{"reestimated_station_bias",false},{"reference_translation",{0,0,0}},{"initial_orientation_source","continuous actual gyro from trusted initial calibration; rigid gauge, not cross-station constraint"}};std::ofstream(directory/"summary.json")<<summary.dump(2)<<'\n';all["stations"].push_back(summary);std::ofstream(out/"summary.json")<<all.dump(2)<<'\n';std::cout<<station.at("id")<<" accepted="<<accepted<<"/"<<poses.size()<<" complete="<<!any_fault<<'\n'<<std::flush;}
return 0;}catch(const std::exception & e){std::cerr<<e.what()<<'\n';return 2;}}
